    61  struct UA_Connection {
    62      UA_ConnectionState state;
    63      UA_ConnectionConfig config;
    64      UA_SecureChannel *channel;       /* The securechannel that is attached to
    65                                        * this connection */
    66      UA_SOCKET sockfd;                 /* Most connectivity solutions run on
    67                                        * sockets. Having the socket id here
    68                                        * simplifies the design. */
    69      UA_DateTime openingDate;         /* The date the connection was created */
    70      void *handle;                    /* A pointer to internal data */
    71      UA_ByteString incompleteChunk;   /* A half-received chunk (TCP is a
    72                                        * streaming protocol) is stored here */
    73      UA_UInt64 connectCallbackID;     /* Callback Id, for the connect-loop */
    74      /* Get a buffer for sending */
    75      UA_StatusCode (*getSendBuffer)(UA_Connection *connection, size_t length,
    76                                     UA_ByteString *buf);
    77
    78      /* Release the send buffer manually */
    79      void (*releaseSendBuffer)(UA_Connection *connection, UA_ByteString *buf);
    80
    81      /* Sends a message over the connection. The message buffer is always freed,
    82       * even if sending fails.
    83       *
    84       * @param connection The connection
    85       * @param buf The message buffer
    86       * @return Returns an error code or UA_STATUSCODE_GOOD. */
    87      UA_StatusCode (*send)(UA_Connection *connection, UA_ByteString *buf);
    88
    89      /* Receive a message from the remote connection
    90       *
    91       * @param connection The connection
    92       * @param response The response string. It is allocated by the connection
    93       *        and needs to be freed with connection->releaseBuffer
    94       * @param timeout Timeout of the recv operation in milliseconds
    95       * @return Returns UA_STATUSCODE_BADCOMMUNICATIONERROR if the recv operation
    96       *         can be repeated, UA_STATUSCODE_GOOD if it succeeded and
    97       *         UA_STATUSCODE_BADCONNECTIONCLOSED if the connection was
    98       *         closed. */
    99      UA_StatusCode (*recv)(UA_Connection *connection, UA_ByteString *response,
   100                            UA_UInt32 timeout);
   101
   102      /* Release the buffer of a received message */
   103      void (*releaseRecvBuffer)(UA_Connection *connection, UA_ByteString *buf);
   104
   105      /* Close the connection. The network layer closes the socket. This is picked
   106       * up during the next 'listen' and the connection is freed in the network
   107       * layer. */
   108      void (*close)(UA_Connection *connection);
   109
   110      /* To be called only from within the server (and not the network layer).
   111       * Frees up the connection's memory. */
   112      void (*free)(UA_Connection *connection);
   113  };
