   157      /* Start listening on the networklayer.
   158       *
   159       * @param nl The network layer
   160       * @return Returns UA_STATUSCODE_GOOD or an error code. */
   161      UA_StatusCode (*start)(UA_ServerNetworkLayer *nl, const UA_String *customHostname);
   162
   163      /* Listen for new and closed connections and arriving packets. Calls
   164       * UA_Server_processBinaryMessage for the arriving packets. Closed
   165       * connections are picked up here and forwarded to
   166       * UA_Server_removeConnection where they are cleaned up and freed.
   167       *
   168       * @param nl The network layer
   169       * @param server The server for processing the incoming packets and for
   170       *               closing connections.
   171       * @param timeout The timeout during which an event must arrive in
   172       *                milliseconds
   173       * @return A statuscode for the status of the network layer. */
   174      UA_StatusCode (*listen)(UA_ServerNetworkLayer *nl, UA_Server *server,
   175                              UA_UInt16 timeout);
