   181  /* This performs only 'shutdown'. 'close' is called when the shutdown
   182   * socket is returned from select. */
   183  static void
   184  ServerNetworkLayerTCP_close(UA_Connection *connection) {
   185      if (connection->state == UA_CONNECTION_CLOSED)
   186          return;
   187      UA_shutdown((UA_SOCKET)connection->sockfd, 2);
   188      connection->state = UA_CONNECTION_CLOSED;
   189  }
