   191  static UA_StatusCode
   192  ServerNetworkLayerTCP_add(UA_ServerNetworkLayer *nl, ServerNetworkLayerTCP *layer,
   193                            UA_Int32 newsockfd, struct sockaddr_storage *remote) {
   194      /* Set nonblocking */
   195      UA_socket_set_nonblocking(newsockfd);//TODO: check return value
   196
   197      /* Do not merge packets on the socket (disable Nagle's algorithm) */
   198      int dummy = 1;
   199      if(UA_setsockopt(newsockfd, IPPROTO_TCP, TCP_NODELAY,
   200                 (const char *)&dummy, sizeof(dummy)) < 0) {
   201          UA_LOG_SOCKET_ERRNO_WRAP(
   202                  UA_LOG_ERROR(layer->logger, UA_LOGCATEGORY_NETWORK,
   203                               "Cannot set socket option TCP_NODELAY. Error: %s",
   204                               errno_str));
   205          return UA_STATUSCODE_BADUNEXPECTEDERROR;
   206      }
   207
   208  #if defined(UA_getnameinfo)
   209      /* Get the peer name for logging */
   210      char remote_name[100];
   211      int res = UA_getnameinfo((struct sockaddr*)remote,
   212                            sizeof(struct sockaddr_storage),
   213                            remote_name, sizeof(remote_name),
   214                            NULL, 0, NI_NUMERICHOST);
   215      if(res == 0) {
   216          UA_LOG_INFO(layer->logger, UA_LOGCATEGORY_NETWORK,
   217                      "Connection %i | New connection over TCP from %s",
   218                      (int)newsockfd, remote_name);
   219      } else {
   220          UA_LOG_SOCKET_ERRNO_WRAP(UA_LOG_WARNING(layer->logger, UA_LOGCATEGORY_NETWORK,
   221                                                  "Connection %i | New connection over TCP, "
   222                                                  "getnameinfo failed with error: %s",
   223                                                  (int)newsockfd, errno_str));
   224      }
   225  #else
   226      UA_LOG_INFO(layer->logger, UA_LOGCATEGORY_NETWORK,
   227                  "Connection %i | New connection over TCP",
   228                  (int)newsockfd);
   229  #endif
   230      /* Allocate and initialize the connection */
   231      ConnectionEntry *e = (ConnectionEntry*)UA_malloc(sizeof(ConnectionEntry));
   232      if(!e){
   233          UA_close(newsockfd);
   234          return UA_STATUSCODE_BADOUTOFMEMORY;
   235      }
   236
   237      UA_Connection *c = &e->connection;
   238      memset(c, 0, sizeof(UA_Connection));
   239      c->sockfd = newsockfd;
   240      c->handle = layer;
   241      c->config = nl->localConnectionConfig;
   242      c->send = connection_write;
   243      c->close = ServerNetworkLayerTCP_close;
   244      c->free = ServerNetworkLayerTCP_freeConnection;
   245      c->getSendBuffer = connection_getsendbuffer;
   246      c->releaseSendBuffer = connection_releasesendbuffer;
   247      c->releaseRecvBuffer = connection_releaserecvbuffer;
   248      c->state = UA_CONNECTION_OPENING;
   249      c->openingDate = UA_DateTime_nowMonotonic();
   250
   251      /* Add to the linked list */
   252      LIST_INSERT_HEAD(&layer->connections, e, pointers);
   253      return UA_STATUSCODE_GOOD;
   254  }
